"""Exercise production startup gates and API logger with deterministic adapters."""
import argparse
from pathlib import Path
from generate_buffer_contract_test import method

ROOT = Path(__file__).resolve().parents[1]


def generate(source, output):
    src = source / 'bridge/src'
    host = (src / 'server/main.cpp').read_text(encoding="utf-8")
    client = (src / 'client/d3d9_lss.cpp').read_text(encoding="utf-8")
    di = (src / 'client/di_hook.cpp').read_text(encoding="utf-8")
    util = (src / 'client/d3d9_util.h').read_text(encoding="utf-8")
    logger = (src / 'util/log/log.h').read_text(encoding="utf-8")
    window = (src / 'client/window.cpp').read_text(encoding="utf-8")
    control = (src / 'client/pageblock_control.cpp').read_text(encoding="utf-8")
    generated = ['#include "runtime_observation_support.h"\n#include <cstdarg>\n']
    readback = (src / 'client/readback_recovery.h').read_text(encoding='utf-8')
    generated.append(readback[readback.index('namespace l4d2_readback {'):] + '\n')
    retention = (src / 'client/retention_runtime.h').read_text(encoding='utf-8')
    start, end = method(retention, 'struct Runtime {')
    generated.append('namespace l4d2_retention {\n' + retention[start:end] + ';\n}\n')
    residency = (src / 'client/pageblock_runtime.h').read_text(encoding='utf-8')
    start, end = method(residency, 'struct Runtime {')
    generated.append('namespace l4d2_residency {\n' + residency[start:end] + ';\n}\n')
    for marker in ['class FunctionEntryExitLogger']:
        start, end = method(util, marker)
        generated.append(util[start:end] + ';\n')
    for marker in ['std::map<std::thread::id, std::atomic<size_t>>& FunctionEntryExitLogger::counters()', 'FunctionEntryExitLogger::FunctionEntryExitLogger(', 'FunctionEntryExitLogger::~FunctionEntryExitLogger(']:
        start, end = method(client, marker)
        generated.append(client[start:end] + '\n')
    # Use the real lazy producer method, not a substitute implementation.
    for name in ['traceLazy', 'debugLazy']:
        start, end = method(logger, 'template<typename Message> static void ' + name)
        generated.append(logger[start:end].replace('static void ' + name, 'void LazyLogger::' + name) + '\n')
    for marker in ['bool DInputHooksEnabled()', 'void DInputHookAttach()', 'void DInputHookDetach()']:
        start, end = method(di, marker)
        generated.append(di[start:end] + '\n')
    for marker in ['static l4d2_host_memory::Recorder& hostMemoryRecorder()', 'static void sampleHostMemory(',
                   'static HWND configureOverlayPresenter(', 'static HWND overlayPresentWindow(']:
        start, end = method(host, marker)
        generated.append(host[start:end] + '\n')
    start, end = method(window, 'void WndProc::sampleSteamInput()')
    generated.append(window[start:end] + '\n')
    start, end = method(control, 'extern "C" HRESULT WINAPI L4D2BridgePageBlockControl(')
    generated.append(control[start:end] + '\n')
    generated.append('#include "runtime_observation_cases.cpp"\n')
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(''.join(generated), encoding='utf-8')


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--source', type=Path, default=ROOT / '.deps/dxvk-remix')
    parser.add_argument('--output', type=Path, required=True)
    args = parser.parse_args()
    generate(args.source, args.output)
